import { Controller } from "react-hook-form";
import type { Control, FieldPath, FieldValues, RegisterOptions } from "react-hook-form";
import { PhoneInput } from "../ui/PhoneInput.tsx";

/** PhoneInput is controlled, so this owns the Controller (REACT-1); callers pass only name + control. */
export function FormPhoneField<T extends FieldValues>({
  name,
  control,
  rules,
}: {
  name: FieldPath<T>;
  control: Control<T>;
  rules?: RegisterOptions<T, FieldPath<T>>;
}) {
  return (
    <Controller
      name={name}
      control={control}
      rules={rules}
      render={({ field, fieldState }) => <PhoneInput {...field} error={fieldState.error?.message} />}
    />
  );
}

